// The CCNA glossary: every term in two layers.
//
//   plain  the concept in one line, the idea everything else hangs off
//   exam   the definition the way the exam words it
//   cmd    the IOS command that shows or sets it, when there is one
//   branch the skill-map branch the term lives on
//   aka    other spellings the text might use (plurals, long forms)
//   auto   false for words so common that linking every one would be noise;
//          they stay searchable in the glossary list
//
// Written for CCNA 200-301 v1.1. Pure data, no DOM.

const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const G = (term, branch, plain, exam, extra = {}) => ({
  id: slug(term), term, branch, plain, exam,
  cmd: extra.cmd ?? null, aka: extra.aka ?? [], auto: extra.auto ?? true,
});

