// Lookups built once.
export const TERM_BY_ID = new Map(GLOSSARY.map(t => [t.id, t]));

export function termsForBranch(branchId) {
  return GLOSSARY.filter(t => t.branch === branchId);
}

// searchGlossary(query) -> terms whose name, aliases or text match, best first:
// an exact name, then a name or alias that starts with the query, then any
// mention in the definitions.
export function searchGlossary(query, terms = GLOSSARY) {
  const q = String(query ?? '').trim().toLowerCase();
  if (!q) return [...terms].sort((a, b) => a.term.localeCompare(b.term));
  const scored = [];
  for (const t of terms) {
    const names = [t.term, ...t.aka].map(n => n.toLowerCase());
    let score = 0;
    if (names.includes(q)) score = 4;
    else if (names.some(n => n.startsWith(q))) score = 3;
    else if (names.some(n => n.includes(q))) score = 2;
    else if (`${t.plain} ${t.exam} ${t.cmd ?? ''}`.toLowerCase().includes(q)) score = 1;
    if (score) scored.push([score, t]);
  }
  return scored.sort((a, b) => b[0] - a[0] || a[1].term.localeCompare(b[1].term)).map(([, t]) => t);
}
